from __future__ import annotations

import json
from pathlib import Path

from monty.json import MontyEncoder

from workflow.archived_campaign import run_archived_campaign


TASK_DIR = Path(__file__).resolve().parent
OUTPUT_DIR = TASK_DIR / "outputs"
DOCUMENT_FILE = OUTPUT_DIR / "elasticity_document.json"
REPORT_FILE = OUTPUT_DIR / "public_reproduction_report.json"


def _reject_non_finite(token: str):
    raise ValueError(f"Non-finite JSON number: {token}")


def _write_report(report: dict[str, object], exit_code: int) -> int:
    OUTPUT_DIR.mkdir(exist_ok=True)
    payload = json.dumps(report, indent=2, sort_keys=True) + "\n"
    REPORT_FILE.write_text(payload, encoding="utf-8")
    print(payload, end="")
    return exit_code


def main() -> int:
    try:
        document = run_archived_campaign()
        encoded = json.dumps(document.dict(), cls=MontyEncoder)
        decoded = json.loads(encoded, parse_constant=_reject_non_finite)
        document_payload = json.dumps(
            decoded,
            allow_nan=False,
            indent=2,
            sort_keys=True,
        ) + "\n"
        if len(document_payload.strip()) <= 2:
            raise ValueError("The workflow produced an empty document")
        OUTPUT_DIR.mkdir(exist_ok=True)
        DOCUMENT_FILE.write_text(document_payload, encoding="utf-8")
    except Exception as error:  # noqa: BLE001 - lifecycle failures need a report.
        return _write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(error).__name__,
                "error": str(error),
            },
            2,
        )

    return _write_report(
        {
            "schema_version": "1.0",
            "status": "workflow_completed",
            "artifact": {
                "path": str(DOCUMENT_FILE.relative_to(TASK_DIR)),
                "document_type": type(document).__name__,
                "bytes": DOCUMENT_FILE.stat().st_size,
            },
        },
        0,
    )


if __name__ == "__main__":
    raise SystemExit(main())

